// Loads the labeled API fixtures generated by the backend (tests/fixtures/*.json).
import { readFileSync } from "node:fs";
import { join } from "node:path";

import { RoutesResponseSchema, type RoutesResponse } from "@/lib/types";

const DIR = join(process.cwd(), "..", "tests", "fixtures");

export function loadFixture(name = "routes_response.json"): RoutesResponse {
  return RoutesResponseSchema.parse(JSON.parse(readFileSync(join(DIR, name), "utf-8")));
}

export function rawFixture(name = "routes_response.json"): unknown {
  return JSON.parse(readFileSync(join(DIR, name), "utf-8"));
}

export function fixtureText(dir: string, name: string): string {
  return readFileSync(join(dir, name), "utf-8");
}

export const FIXTURE_DIR = DIR;
